def transform(grid):
    h, w = len(grid), len(grid[0])
    counts = {}
    for row in grid:
        for v in row:
            counts[v] = counts.get(v, 0) + 1
    bg = max(counts, key=counts.get)

    seen = [[False] * w for _ in range(h)]
    rectangles = []

    for r in range(h):
        for c in range(w):
            color = grid[r][c]
            if color == bg or seen[r][c]:
                continue

            stack = [(r, c)]
            seen[r][c] = True
            cells = []
            while stack:
                y, x = stack.pop()
                cells.append((y, x))
                for dy, dx in ((1, 0), (-1, 0), (0, 1), (0, -1)):
                    ny, nx = y + dy, x + dx
                    if (0 <= ny < h and 0 <= nx < w and
                            not seen[ny][nx] and grid[ny][nx] == color):
                        seen[ny][nx] = True
                        stack.append((ny, nx))

            r0 = min(y for y, x in cells)
            r1 = max(y for y, x in cells)
            c0 = min(x for y, x in cells)
            c1 = max(x for y, x in cells)
            rh, cw = r1 - r0 + 1, c1 - c0 + 1
            area = rh * cw
            if rh >= 2 and cw >= 2 and area >= 4 and len(cells) / area >= 0.55:
                rectangles.append((r0, r1, c0, c1, color))

    out = [[bg] * w for _ in range(h)]
    for r0, r1, c0, c1, color in rectangles:
        for r in range(r0, r1 + 1):
            for c in range(c0, c1 + 1):
                out[r][c] = color
    return out
